#pragma once
static void checkCurrentFishhooks(App& app,const std::string& dir){
    const auto fixture=dir+"/user-mass-fishhook-input.r62doc";if(GetFileAttributesW(W(fixture).c_str())==INVALID_FILE_ATTRIBUTES)return;
    auto require=[](bool ok,const std::string& why){if(!ok)throw std::runtime_error("current fishhooks: "+why);};auto& s=app.s;
    for(int stage:{0,1}){
        s.cancel();s.history.clear();require(s.open(fixture).ok(),"open current live fishhook copy");std::vector<ObjectId> ids=stage?std::vector<ObjectId>{13,14,15}:std::vector<ObjectId>{9,10,11};Document routing=s.doc;for(auto id:ids)routing.removeObject(ObjectRef(ObjectKind::Arrow,id));
        for(auto id:ids){arrows::ArrowParams p;bool ok=false;arrows::readArrow(s.doc,id,&p,&ok);require(ok,"actual hook parameters");arrows::mechanismAnchorPoint(s.doc,p.electronSource,&p.begin);if(p.electronTarget.valid())arrows::mechanismAnchorPoint(s.doc,p.electronTarget,&p.end);p.route.clear();arrows::routeMechanism(routing,p);arrows::clearMechanismLabels(routing,p);arrows::orientAutomaticFishhook(p);
            arrows::ArrowGeometry g;require(arrows::buildArrowGeometry(p,.6,arrows::Tessellation(),&g).ok()&&g.heads.size()==1&&g.heads.front().filled&&g.heads.front().outline.size()==3,"actual fishhook has one visible barb");const auto& points=g.shafts.front();auto tip=g.heads.front().tip,wing=g.heads.front().outline[1];double gap=1e30;
            for(size_t k=1;k<points.size();++k){if(length(points[k]-tip)<1e-6)continue;gap=std::min(gap,mechanism::step_detail::pointSegment(wing,points[k-1],points[k]));require(!mechanism::step_detail::segmentsCross(wing,tip,points[k-1],points[k]),"actual hooked head never folds through its shaft");}
            require(gap>.45,"actual barb remains separated from its curved shaft");require(arrows::writeArrow(s.doc,id,p,.6).ok(),"save rerouted actual hook");
        }
        auto before=s.doc.digest();auto count=s.doc.stats().aliveAtoms;s.selected.clear();for(auto id:ids)s.selected.emplace_back(ObjectKind::Arrow,id);app.generateMechanismStep();require(s.doc.stats().aliveAtoms==count+16,"actual three-hook stage creates sixteen product atoms");
        std::map<ObjectId,ObjectId> copied;for(auto ref:s.selected)if(ref.kind==ObjectKind::Atom)copied[studio_mechanism_products::sourceAtom(s.doc,ref.id)]=ref.id;
        auto radical=copied.at(stage?79:71);require(s.doc.atoms().alive(radical)->semantics.radical==uint8_t(Radical::Doublet),"actual carbon receives its single unpaired electron");auto dots=arrows::mechanismRadicalPoints(s.doc,radical);auto center=s.doc.atoms().alive(radical)->position;require(dots.size()==1,"actual generated carbon has one radical dot");if(stage)require(std::abs(dots[0].x-center.x)<1e-7&&dots[0].y<center.y,"unblocked skeletal radical remains directly overhead");else{auto stem=s.doc.atoms().alive(copied.at(73))->position-center;require(dot(dots[0]-center,stem)<0,"thiocarbonyl adduct radical occupies the opposite free bisector");}for(auto bid:s.doc.incidentBonds(radical)){auto b=s.doc.bonds().alive(bid);auto other=s.doc.atoms().alive(b->beginAtom==radical?b->endAtom:b->beginAtom);require(mechanism::step_detail::pointSegment(dots[0],center,other->position)>arrows::mechanismRadicalRadius(s.doc,radical)+.5,"actual radical never overlaps an incident bond");}
        if(stage)require(s.doc.bondBetween(copied.at(79),copied.at(87))==kInvalidObjectId&&s.doc.bonds().alive(s.doc.bondBetween(copied.at(87),copied.at(88)))->order==BondOrder::Double,"actual scission breaks ring C--O and forms carbonyl");
        else require(s.doc.bondBetween(copied.at(57),copied.at(73))!=kInvalidObjectId&&s.doc.bonds().alive(s.doc.bondBetween(copied.at(71),copied.at(73)))->order==BondOrder::Single,"actual tin radical couples to sulfur and reduces thiocarbonyl");
        auto excerpt=s.selected;for(ObjectId id=stage?77:60;id<=(stage?92:74);++id)excerpt.emplace_back(ObjectKind::Atom,id);if(!stage)excerpt.emplace_back(ObjectKind::Atom,57);
        std::set<ObjectId> selectedAtoms;for(auto ref:excerpt)if(ref.kind==ObjectKind::Atom)selectedAtoms.insert(ref.id);for(const auto& b:s.doc.bonds().records())if(b.isAlive()&&selectedAtoms.count(b.beginAtom)&&selectedAtoms.count(b.endAtom))excerpt.emplace_back(ObjectKind::Bond,b.id);for(auto id:ids)excerpt.emplace_back(ObjectKind::Arrow,id);
        Session clean;clean.doc.setDefaultFont(s.doc.defaultFont());require(studioio::append(s.doc,clean.doc,excerpt,Vec2(),nullptr).ok()&&clean.save(dir+(stage?"/current-radical-scission.cdxml":"/current-tin-radical-addition.cdxml"),true).ok(),"save current corrected reaction example");require(s.undo().ok()&&s.doc.digest()==before,"actual fishhook product undoes atomically");
    }
    std::ofstream(dir+"/current-fishhook-checks.json")<<"{\"actual_stages\":2,\"actual_arrows\":6,\"barbs_clear\":true,\"new_radical_free_bisector\":true}";
}
